package main
import (
 "context"
 "encoding/json"
 "os"
 "runtime"
 "strconv"
 "unsafe"
 "github.com/cpunion/wasmvm/pkg/vm"
)
func empty(*vm.Caller) error { return nil }
//go:noinline
func public(fn vm.Extern,args []vm.Value) uint64 {
 result,err:=fn.Call(context.Background(),args,vm.CallOptions{});if err!=nil {panic(err)}
 if len(result.Values)!=1 {panic("arity")};lo,hi,err:=result.Values[0].Bits();if err!=nil||lo!=0x12345678||hi!=0 {panic("result")};return lo
}
//go:noinline
func nested(c *vm.Caller,fn vm.Extern,args []vm.Value) uint64 {
 result,err:=c.Call(fn,args);if err!=nil {panic(err)}
 if len(result.Values)!=1 {panic("arity")};lo,hi,err:=result.Values[0].Bits();if err!=nil||lo!=0x12345678||hi!=0 {panic("result")};return lo
}
func main(){
 if len(os.Args)!=5 {panic("mode backend fixture count")};n,err:=strconv.Atoi(os.Args[4]);if err!=nil||n<1 {panic("count")}
 input,err:=os.ReadFile(os.Args[3]);if err!=nil {panic(err)}
 config:=vm.DefaultEngineConfig();config.Backend=os.Args[2]
 engine,err:=vm.NewEngineWithConfig(config);if err!=nil {panic(err)}
 store,err:=engine.NewStore(vm.DefaultStoreConfig());if err!=nil {panic(err)}
 module,err:=engine.Compile(nil,input);if err!=nil {panic(err)}
 instance,err:=vm.NewLinker(store).Instantiate(nil,module,vm.CallOptions{});if err!=nil {panic(err)}
 fn,err:=instance.Export("run");if err!=nil {panic(err)}
 args:=[]vm.Value{vm.I32(0x12345678),vm.I32(1)}
 for range 1000 {public(fn,args)}
 runtime.GC();var before,after runtime.MemStats;runtime.ReadMemStats(&before)
 var checked uint64
 switch os.Args[1] {
 case "public":for range n {checked+=public(fn,args)}
 case "session":
  _,err=store.WithCaller(context.Background(),vm.CallOptions{},func(c *vm.Caller)error{for range n {checked+=nested(c,fn,args)};return nil});if err!=nil {panic(err)}
 case "empty-operation":for range n {_,err=store.WithCaller(context.Background(),vm.CallOptions{},empty);if err!=nil {panic(err)};checked++}
 case "context":for range n {ctx,cancel:=context.WithCancel(context.Background());if ctx.Err()!=nil {panic("context")};cancel();checked++}
 case "context-done":for range n {ctx,cancel:=context.WithCancel(context.Background());if ctx.Done()==nil {panic("context")};cancel();checked++}
 default:panic("mode")
 }
 runtime.ReadMemStats(&after)
 if (os.Args[1]=="public"||os.Args[1]=="session") && checked!=uint64(n)*0x12345678 {panic("checksum")}
 store.Close();if err:=store.WaitClosed(context.Background());err!=nil {panic(err)};module.Close();engine.Close()
 if err:=json.NewEncoder(os.Stdout).Encode(struct{Mode,Backend,Compiler,Runtime string;Count int;CheckedSum,TotalAlloc,ExternBytes,ValueBytes uint64}{os.Args[1],config.Backend,runtime.Compiler,runtime.Version(),n,checked,after.TotalAlloc-before.TotalAlloc,uint64(unsafe.Sizeof(fn)),uint64(unsafe.Sizeof(vm.Value{}))});err!=nil {panic(err)}
}

