package main

import (
 "encoding/json"
 "os"
 "runtime"
 "strconv"
 "unsafe"
)

type descriptor struct { owner *uint64; kind byte; function uint64; table, memory, global, tag *uint64 }
type external struct { store *uint64; object descriptor }
type handle struct { store *uint64; object *descriptor }

//go:noinline
func (e external) call(seed uint64) uint64 { return e.object.function ^ seed }
//go:noinline
func (h handle) call(seed uint64) uint64 { return h.object.function ^ seed }
//go:noinline
func pointerCall(e *external, seed uint64) uint64 { return e.object.function ^ seed }
//go:noinline
func copied(e *external) external { return *e }

func main() {
 if len(os.Args)!=3 { panic("mode count") }
 n,err:=strconv.Atoi(os.Args[2]);if err!=nil||n<1 {panic("count")}
 var owner uint64
 e:=external{store:&owner,object:descriptor{owner:&owner,function:0x12345678}}
 h:=handle{store:&owner,object:&e.object}
 runtime.GC()
 var before,after runtime.MemStats
 runtime.ReadMemStats(&before)
 var checksum uint64
 switch os.Args[1] {
 case "large-receiver":
  for i:=0;i<n;i++ { checksum+=e.call(uint64(i)) }
 case "small-receiver":
  for i:=0;i<n;i++ { checksum+=h.call(uint64(i)) }
 case "pointer-argument":
  for i:=0;i<n;i++ { checksum+=pointerCall(&e,uint64(i)) }
 case "large-return":
  for i:=0;i<n;i++ { r:=copied(&e);checksum+=r.object.function^uint64(i) }
 case "empty":
  for i:=0;i<n;i++ { checksum+=e.object.function^uint64(i) }
 default:panic("mode")
 }
 runtime.ReadMemStats(&after)
 expected:=uint64(0);for i:=0;i<n;i++ {expected+=0x12345678^uint64(i)}
 if checksum!=expected {panic("checksum")}
 runtime.KeepAlive(e);runtime.KeepAlive(h)
 if err:=json.NewEncoder(os.Stdout).Encode(struct{Mode string;Count int;CheckedSum,TotalAlloc,ExternalBytes,HandleBytes uint64;Compiler,Runtime string}{os.Args[1],n,checksum,after.TotalAlloc-before.TotalAlloc,uint64(unsafe.Sizeof(e)),uint64(unsafe.Sizeof(h)),runtime.Compiler,runtime.Version()});err!=nil {panic(err)}
}
